  loads.Controls.Add(act);loads.Controls.Add(reactions);Inputs.Add("Reactions",reactions);loads.Controls.Add(loaded);reactions.TextChanged+=(s,e)=>{if(!Restoring)Refresh0();};
  var plate=Section("Plate and anchors","Bearing plate centred on the RC column / beam top, a gusset along the plate length, anchors in two rows - one each side of the gusset. Cast-in anchors per NSCP 2015 Section 417, condition B (no supplementary reinforcement).");
  NumberField(plate,"PlateB","Plate width B across the gusset (mm)","300");NumberField(plate,"PlateN","Plate length N along the gusset (mm)","300");NumberField(plate,"PlateT","Plate thickness (mm)","12");NumberField(plate,"PlateFy","Plate Fy (MPa)","248");
