  Choice(plate,"AnchorSize","Anchor bolt (Powersteel A x B x C x D)",new[]{"Custom (enter the diameter and hef)"}.Concat(AnchorBolts.Powersteel.Select(a=>a.Name)).ToArray());Choice(plate,"BoltDia","Anchor diameter",AnchorBolts.DiameterLabels).SelectedItem="3/4 in (19.1 mm)";Choice(plate,"BoltColumns","Anchors each side of the gusset",new[]{"1","2","3","4","5","6","7","8"});NumberField(plate,"BoltS2","Anchor gauge across the gusset (mm)","200");NumberField(plate,"BoltS1","Anchor pitch along the gusset (mm)","150");
  NumberField(plate,"Hef","Embedment hef (mm)","300");Choice(plate,"AnchorType","Anchor type",new[]{"Headed (nut / head)","Hooked J or L bolt"});NumberField(plate,"HookEh","Hook length eh (mm, J/L bolt)","80");Choice(plate,"AnchorGrade","Anchor material",new[]{"A36 / A307 (futa 400, fya 250)","A325 (futa 825, fya 635)","F1554 Gr 55 (futa 517, fya 380)","F1554 Gr 105 (futa 862, fya 724)","Custom"});NumberField(plate,"Futa","Anchor futa (MPa)","400");NumberField(plate,"Fya","Anchor fya (MPa)","250");
  Toggle(plate,"Cracked","Cracked concrete (normal assumption)",true);Toggle(plate,"Grout","Grout pad under the plate (0.8 Vsa)",true);
  var presets=new FlowLayoutPanel{Width=1000,Height=46,Tag="FullWidth"};var typical=new Button{Text="Detail 6: 300 x 250 x 16 plate, 2-20 mm L anchor bolts each side",AutoSize=true,Height=32};typical.Click+=(s,e)=>Typical();presets.Controls.Add(typical);var truss2=new Button{Text="Truss 2 anchorage: 350 x 1000 x 20 plate, 10-20 mm A325 L anchor bolts",AutoSize=true,Height=32};truss2.Click+=(s,e)=>Truss2();presets.Controls.Add(truss2);
  ((ComboBox)Inputs["AnchorGrade"]).SelectedIndexChanged+=(s,e)=>{if(Restoring)return;var m=System.Text.RegularExpressions.Regex.Match(Value("AnchorGrade"),@"futa (\d+), fya (\d+)");if(!m.Success)return;Restoring=true;try{Inputs["Futa"].Text=m.Groups[1].Value;Inputs["Fya"].Text=m.Groups[2].Value;}finally{Restoring=false;}Refresh0();};plate.Controls.Add(presets);plate.Controls.Add(sketch);
  /* the model sits at the top of the tab and edits the inputs it shows */plate.Controls.SetChildIndex(sketch,1);plate.Controls.SetChildIndex(presets,2);
  sketch.ValueChanged+=(key,value)=>{Control box;if(Inputs.TryGetValue(key,out box))box.Text=value.ToString("0.###",Inv);};
  var member=Section("Gusset and angle","The truss end member (1L or 2L angle) is welded to the gusset with heel and toe fillet welds; the gusset is fillet welded on both sides to the plate. Enter the member force from STAAD (Beam End Forces, axial; + tension, - compression) or leave it blank to use the support reaction.");
  Choice(member,"PlateConnection","What is welded to the base plate",new[]{"Bottom chord angles (anchors outside the angles)","Gusset plate (fillet welds both sides)"});Choice(member,"Chord","Bottom chord angle section",SteelCatalog.Profiles.Where(p=>p.Kind=="Angle bar").Select(p=>p.Name).ToArray()).SelectedItem="L50x50x5mm (PNS)";Choice(member,"ChordAngles","Bottom chord",new[]{"2L (back to back)","1L"});NumberField(member,"ChordWeld","Chord-to-plate fillet weld (mm)","6");NumberField(member,"ChordWeldLength","Chord weld length on the plate (mm, blank = plate length)","");
  NumberField(member,"GussetT","Gusset thickness tg (mm)","10");NumberField(member,"GussetL","Gusset length Lg (mm)","250");NumberField(member,"GussetH","Gusset height (mm, drawing only)","250");NumberField(member,"GussetFy","Gusset Fy (MPa)","248");NumberField(member,"GussetFu","Gusset Fu (MPa)","400");NumberField(member,"PlateWeld","Gusset-to-plate fillet weld (mm)","6");NumberField(member,"Lc","Gusset free length for buckling Lc (mm)","150");Toggle(member,"Bearing","Compression transferred by bearing",true);
  Choice(member,"Angles","Angle member",new[]{"2L (back to back)","1L"});angle=Choice(member,"Angle","Angle section (Regan handbook)",SteelCatalog.Profiles.Where(p=>p.Kind=="Angle bar").Select(p=>p.Name).ToArray());NumberField(member,"MemberForce","Member force from STAAD (kN, blank = reaction)","");
  NumberField(member,"HeelWeld","Heel weld length per angle (mm)","100");NumberField(member,"ToeWeld","Toe weld length per angle (mm)","60");NumberField(member,"AngleWeld","Angle fillet weld size (mm)","6");NumberField(member,"Fexx","Electrode FEXX (MPa, E70 = 482)","482");NumberField(member,"AngleFy","Angle Fy (MPa)","248");NumberField(member,"AngleFu","Angle Fu (MPa)","400");
  member.Controls.Add(new Label{Text="OTHER MEMBERS AT THE JOINT (bottom chord, vertical post, diagonal) - STAAD axial force, + tension / - compression",Width=1000,Height=30,Tag="FullWidth",Font=ModernUi.Strong,ForeColor=PowTheme.Teal,Padding=new Padding(0,8,0,0)});
  others.Columns.Add("Name","MEMBER");var count=new DataGridViewComboBoxColumn{Name="Angles",HeaderText="ANGLES",FlatStyle=FlatStyle.Flat};count.Items.AddRange("2L","1L");others.Columns.Add(count);var section=new DataGridViewComboBoxColumn{Name="Section",HeaderText="ANGLE SECTION",FlatStyle=FlatStyle.Flat,FillWeight=170};foreach(var p in SteelCatalog.Profiles.Where(p=>p.Kind=="Angle bar"))section.Items.Add(p.Name);others.Columns.Add(section);
  foreach(var c in new[]{new[]{"Force","FORCE (kN)"},new[]{"Heel","HEEL WELD (mm)"},new[]{"Toe","TOE WELD (mm)"},new[]{"Weld","WELD SIZE (mm)"}})others.Columns.Add(c[0],c[1]);others.DefaultValuesNeeded+=(s,e)=>{e.Row.Cells["Name"].Value="Diagonal";e.Row.Cells["Angles"].Value="2L";e.Row.Cells["Section"].Value=angle.Text;e.Row.Cells["Heel"].Value="100";e.Row.Cells["Toe"].Value="60";e.Row.Cells["Weld"].Value="6";};
  others.CellValueChanged+=(s,e)=>{if(!Restoring)Refresh0();};others.RowsRemoved+=(s,e)=>{if(!Restoring)Refresh0();};others.DataError+=(s,e)=>{e.ThrowException=false;};others.CurrentCellDirtyStateChanged+=(s,e)=>{if(others.IsCurrentCellDirty&&others.CurrentCell is DataGridViewComboBoxCell)others.CommitEdit(DataGridViewDataErrorContexts.Commit);};member.Controls.Add(others);
  var page=new TabPage("Results");foreach(var h in new[]{"CHECK","NSCP / AISC","GOVERNING NODE","LOAD CASE","DEMAND","CAPACITY","RATIO","RESULT"})results.Columns.Add("c"+results.Columns.Count,h);results.Dock=DockStyle.Fill;page.Controls.Add(results);AddResultPage(page);
  foreach(var c in Inputs.Values){c.TextChanged+=(s,e)=>{if(!Restoring)Refresh0();};var combo=c as ComboBox;if(combo!=null)combo.SelectedIndexChanged+=(s,e)=>{if(!Restoring)Refresh0();};var box=c as CheckBox;if(box!=null)box.CheckedChanged+=(s,e)=>{if(!Restoring)Refresh0();};}
  /* a Powersteel size fills the diameter, hook and embedment (length less what projects above the concrete) */
  ((ComboBox)Inputs["AnchorSize"]).SelectedIndexChanged+=(s,e)=>{if(!Restoring)ApplyAnchorSize();};foreach(var key in new[]{"PlateT"})Inputs[key].TextChanged+=(s,e)=>{if(!Restoring&&PowersteelSize()!=null)ApplyAnchorSize();};((CheckBox)Inputs["Grout"]).CheckedChanged+=(s,e)=>{if(!Restoring&&PowersteelSize()!=null)ApplyAnchorSize();};
  ((ComboBox)Inputs["AnchorSize"]).SelectedItem=AnchorBolts.Powersteel.First(a=>a.Name.StartsWith("Ø3/4\" x 12\"")).Name;
  Shown+=(s,e)=>Refresh0();}
 AnchorBolts.Size PowersteelSize(){return AnchorBolts.Powersteel.FirstOrDefault(a=>a.Name==Value("AnchorSize"));}
 void ApplyAnchorSize(){var a=PowersteelSize();if(a==null)return;double t;if(!double.TryParse(Value("PlateT"),NumberStyles.Float,Inv,out t))return;double hef=a.LengthIn*25.4-AnchorBolts.Projection(a.DiaMm,t,((CheckBox)Inputs["Grout"]).Checked)-a.DiaMm;Restoring=true;try{((ComboBox)Inputs["BoltDia"]).SelectedItem=AnchorBolts.Label(a.DiaMm);Inputs["HookEh"].Text=(a.HookIn*25.4).ToString("0",Inv);Inputs["Hef"].Text=Math.Max(10,hef).ToString("0",Inv);((ComboBox)Inputs["AnchorType"]).SelectedIndex=1;}finally{Restoring=false;}Refresh0();}
 protected override bool OptionalSavedInput(string key){return key=="AnchorSize"||key=="Nodes"||key=="MemberForce"||key=="GussetH"||key=="AnchorGrade"||key=="PlateConnection"||key=="Chord"||key=="ChordAngles"||key=="ChordWeld"||key=="ChordWeldLength";}
 /* owner's "Detail of Truss 2 anchorage": 350 x 1000 x 20 mm A36 base plate on the concrete gutter, 10 - 20 mm x 500 mm A325 L anchor bolts
    (5 each side at 225 mm, 50 mm from the plate ends and edges, 250 mm apart), minimum embedment 350 mm; the gutter width / depth and the
    truss depth at the support are starting values to confirm */
 void Truss2(){var values=new Dictionary<string,string>{{"PlateN","1000"},{"PlateB","350"},{"PlateT","20"},{"PlateFy","248"},{"SupportN","1100"},{"SupportB","500"},{"SupportDepth","700"},{"BoltS2","250"},{"BoltS1","225"},{"Hef","350"},{"HookEh","80"},{"Futa","825"},{"Fya","635"},{"GussetL","1000"},{"GussetH","400"}};Restoring=true;try{foreach(var v in values)Inputs[v.Key].Text=v.Value;((ComboBox)Inputs["AnchorSize"]).SelectedItem=AnchorBolts.Powersteel.First(a=>a.Name.StartsWith("Ø3/4\" x 18\" (hook 4\", thread 7\")")).Name;((ComboBox)Inputs["BoltColumns"]).SelectedItem="5";((ComboBox)Inputs["AnchorType"]).SelectedIndex=1;((ComboBox)Inputs["AnchorGrade"]).SelectedIndex=1;((ComboBox)Inputs["PlateConnection"]).SelectedIndex=0;((ComboBox)Inputs["Chord"]).SelectedItem="L75x75x6mm (PNS)";((ComboBox)Inputs["ChordAngles"]).SelectedIndex=0;Inputs["ChordWeldLength"].Text="";}finally{Restoring=false;}ApplyAnchorSize();}
 /* Detail 6 of the owner's drawing: 250 x 300 x 16 base plate (250 along the truss), 2-20 mm x 300 mm long L anchor bolts each side
    of the truss at 50 mm from the plate edges and 90 mm apart, 6 mm gusset 320 x 250 */
 void Typical(){var values=new Dictionary<string,string>{{"PlateN","250"},{"PlateB","300"},{"PlateT","16"},{"SupportB","300"},{"SupportN","300"},{"BoltS2","200"},{"BoltS1","90"},{"Hef","240"},{"HookEh","80"},{"GussetT","6"},{"GussetL","320"},{"GussetH","250"},{"Futa","400"},{"Fya","250"}};Restoring=true;try{foreach(var v in values)Inputs[v.Key].Text=v.Value;((ComboBox)Inputs["AnchorSize"]).SelectedItem=AnchorBolts.Powersteel.First(a=>a.Name.StartsWith("Ø3/4\" x 12\"")).Name;((ComboBox)Inputs["BoltColumns"]).SelectedItem="2";((ComboBox)Inputs["AnchorType"]).SelectedIndex=1;((ComboBox)Inputs["AnchorGrade"]).SelectedIndex=0;((ComboBox)Inputs["PlateConnection"]).SelectedIndex=0;((ComboBox)Inputs["Chord"]).SelectedItem="L50x50x5mm (PNS)";((ComboBox)Inputs["ChordAngles"]).SelectedIndex=0;Inputs["ChordWeldLength"].Text="";}finally{Restoring=false;}ApplyAnchorSize();}
 protected override void WriteAdditionalState(System.Xml.XmlElement root){foreach(DataGridViewRow r in others.Rows){if(r.IsNewRow)continue;var e=root.OwnerDocument.CreateElement("JointMember");foreach(DataGridViewColumn c in others.Columns)e.SetAttribute(c.Name.ToLowerInvariant(),Convert.ToString(r.Cells[c.Index].Value,Inv));root.AppendChild(e);}}
 protected override void ReadAdditionalState(System.Xml.XmlElement root){others.Rows.Clear();foreach(System.Xml.XmlElement e in root.SelectNodes("JointMember")){int i=others.Rows.Add();foreach(DataGridViewColumn c in others.Columns){string v=e.GetAttribute(c.Name.ToLowerInvariant());var combo=c as DataGridViewComboBoxColumn;if(combo!=null&&!combo.Items.Contains(v))continue;others.Rows[i].Cells[c.Index].Value=v;}}}
 List<JointMember> OtherMembers(){var list=new List<JointMember>();foreach(DataGridViewRow r in others.Rows){if(r.IsNewRow)continue;Func<string,string> cell=n=>Convert.ToString(r.Cells[n].Value,Inv).Trim();if(cell("Section")==""&&cell("Force")=="")continue;Func<string,double> num=n=>{double v;if(!double.TryParse(cell(n),NumberStyles.Float,Inv,out v))throw new Exception("Other members row "+(r.Index+1)+": enter "+others.Columns[n].HeaderText.ToLowerInvariant()+" as a number.");return v;};
   list.Add(new JointMember{Name=cell("Name")==""?"Member "+(r.Index+2):cell("Name"),Angles=cell("Angles")=="1L"?1:2,Angle=SteelCatalog.Find(cell("Section")),Force=num("Force"),HeelWeld=num("Heel"),ToeWeld=num("Toe"),Weld=num("Weld")});}return list;}
 internal List<SupportReaction> Rows(out string unit){var all=TrussSupport.Reactions(reactions.Text,out unit);var wanted=Value("Nodes").Split(new[]{',',' ',';'},StringSplitOptions.RemoveEmptyEntries).ToList();if(wanted.Count==0)return all;var list=all.Where(r=>wanted.Contains(r.Node.Split(' ')[0])).ToList();if(list.Count==0)throw new Exception("None of the nodes "+string.Join(", ",wanted)+" is in the reactions.");return list;}
 internal TrussSupportInput Input(){Func<string,double> n=Number;string force=Value("MemberForce");return new TrussSupportInput{PlateB=n("PlateB"),PlateN=n("PlateN"),PlateT=n("PlateT"),PlateFy=n("PlateFy"),Fc=n("Fc"),SupportB=n("SupportB"),SupportN=n("SupportN"),SupportDepth=n("SupportDepth"),BoltDia=AnchorBolts.ParseDiameter(Value("BoltDia")),BoltName=PowersteelSize()==null?"":PowersteelSize().Name,ThreadLength=PowersteelSize()==null?0:PowersteelSize().ThreadIn*25.4,BoltColumns=int.Parse(Value("BoltColumns"),Inv),BoltS1=n("BoltS1"),BoltS2=n("BoltS2"),Hef=n("Hef"),Futa=n("Futa"),Fya=n("Fya"),HookEh=n("HookEh"),Headed=Value("AnchorType").StartsWith("Headed"),Cracked=((CheckBox)Inputs["Cracked"]).Checked,GroutPad=((CheckBox)Inputs["Grout"]).Checked,
  GussetT=n("GussetT"),GussetL=n("GussetL"),GussetFy=n("GussetFy"),GussetFu=n("GussetFu"),PlateWeld=n("PlateWeld"),Fexx=n("Fexx"),Lc=n("Lc"),BearingCompression=((CheckBox)Inputs["Bearing"]).Checked,Angle=SteelCatalog.Find(Value("Angle")),Angles=Value("Angles").StartsWith("2L")?2:1,MemberForce=force==""?double.NaN:n("MemberForce"),HeelWeld=n("HeelWeld"),ToeWeld=n("ToeWeld"),AngleWeld=n("AngleWeld"),AngleFy=n("AngleFy"),AngleFu=n("AngleFu"),Vertical=Value("Vertical"),Others=OtherMembers(),ChordOnPlate=Value("PlateConnection").StartsWith("Bottom chord"),Chord=SteelCatalog.Find(Value("Chord")),ChordAngles=Value("ChordAngles").StartsWith("2L")?2:1,ChordWeld=n("ChordWeld"),ChordWeldLength=Value("ChordWeldLength")==""?0:n("ChordWeldLength")};}
 List<SupportCheck> lastChecks;List<string> lastNotes;
 void Refresh0(){sketch.Failing.Clear();try{double gh;sketch.Show(Input(),double.TryParse(Value("GussetH"),NumberStyles.Float,Inv,out gh)?gh:250);}catch(Exception){sketch.Show(null,0);}results.Rows.Clear();if(reactions.Text.Trim()==""){loaded.Text="No reactions yet. Paste or import the STAAD Support Reactions table.";return;}
  try{string unit;var rows=Rows(out unit);loaded.ForeColor=PowTheme.Muted;loaded.Text=rows.Count+" reaction rows, "+rows.Select(r=>r.Node).Distinct().Count()+" node(s), "+rows.Select(r=>r.Case).Distinct().Count()+" load case(s); unit "+unit+". Largest downward "+TrussSupport.F(rows.Max(r=>Value("Vertical")=="Z"?r.Fz:r.Fy))+" kN, largest uplift "+TrussSupport.F(Math.Max(0,-rows.Min(r=>Value("Vertical")=="Z"?r.Fz:r.Fy)))+" kN.";
   var notes=new List<string>();var checks=TrussSupport.Check(Input(),rows,notes);lastChecks=checks;lastNotes=notes;
   foreach(var c in checks){int i=results.Rows.Add(c.Name,c.Clause,c.Node,c.Case,TrussSupport.F(c.Demand,"0.00")+" "+c.Unit,TrussSupport.F(c.Capacity,"0.00")+" "+c.Unit,TrussSupport.F(c.Ratio,"0.00"),c.Ok?"OK":"NG");if(!c.Ok)results.Rows[i].DefaultCellStyle.ForeColor=Color.Firebrick;}
   sketch.Failing.Clear();foreach(var c in checks.Where(x=>!x.Ok)){string n=c.Name.ToLowerInvariant();if(n.Contains("anchor")||n.Contains("breakout")||n.Contains("pullout")||n.Contains("pryout")||n.Contains("interaction"))sketch.Failing.Add("anchors");else if(n.Contains("plate thickness")||n.Contains("bearing"))sketch.Failing.Add("plate");else if(n.Contains("gusset")||n.Contains("whitmore"))sketch.Failing.Add("gusset");else sketch.Failing.Add("welds / members");}sketch.Invalidate();
   int ng=checks.Count(c=>!c.Ok);loaded.ForeColor=ng>0?Color.Firebrick:PowTheme.Teal;loaded.Text+="\r\n"+(ng>0?ng+" check(s) NG - see Results.":"All checks pass - largest ratio "+TrussSupport.F(checks.Max(c=>c.Ratio),"0.00")+".");}
  catch(Exception ex){lastChecks=null;loaded.ForeColor=Color.Firebrick;loaded.Text=ex.Message;}}
 protected override void AfterRestore(){Refresh0();}
 protected override string BuildReport(){string unit;var rows=Rows(out unit);var input=Input();var notes=new List<string>();var checks=TrussSupport.Check(input,rows,notes);var b=new StringBuilder();
  b.AppendLine("TRUSS SUPPORT ON RC COLUMN / BEAM - BEARING PLATE, ANCHORS AND "+(input.Angles==2?"2L":"1L")+" ANGLE");b.AppendLine();
  b.AppendLine("## 01  DESIGN BASIS");b.AppendLine("LRFD, NSCP 2015: Section 417 (anchoring to concrete, ACI 318-14 Ch. 17), Section 510.8 (bearing), Chapter 5 / AISC 360-10 (steel, welds). STAAD factored support reactions, unit "+unit+"; vertical axis "+input.Vertical+" (positive = downward load on the support).");b.AppendLine();
  b.AppendLine("## 02  INPUTS");b.AppendLine("Plate "+TrussSupport.F(input.PlateB,"0")+" x "+TrussSupport.F(input.PlateN,"0")+" x "+TrussSupport.F(input.PlateT,"0")+" mm, Fy "+TrussSupport.F(input.PlateFy,"0")+" MPa; RC support "+TrussSupport.F(input.SupportB,"0")+" x "+TrussSupport.F(input.SupportN,"0")+" mm, depth "+TrussSupport.F(input.SupportDepth,"0")+" mm, fc' "+TrussSupport.F(input.Fc,"0.#")+" MPa.");
  b.AppendLine("Gusset "+TrussSupport.F(input.GussetT,"0")+" x "+TrussSupport.F(input.GussetL,"0")+" mm (Fy "+TrussSupport.F(input.GussetFy,"0")+", Fu "+TrussSupport.F(input.GussetFu,"0")+" MPa), "+TrussSupport.F(input.PlateWeld,"0")+" mm fillet both sides; angle "+(input.Angles==2?"2L ":"1L ")+input.Angle.Name+", heel / toe welds "+TrussSupport.F(input.HeelWeld,"0")+" / "+TrussSupport.F(input.ToeWeld,"0")+" mm x "+TrussSupport.F(input.AngleWeld,"0")+" mm, FEXX "+TrussSupport.F(input.Fexx,"0")+" MPa.");
  foreach(var n in notes)b.AppendLine(n);b.AppendLine();
  b.AppendLine("## 03  STAAD SUPPORT REACTIONS (kN)");b.AppendLine("Node      L/C                     Fx         Fy         Fz");foreach(var r in rows.Take(60))b.AppendLine(r.Node.PadRight(10)+(r.Case.Length>22?r.Case.Substring(0,22):r.Case).PadRight(24)+TrussSupport.F(r.Fx,"0.00").PadLeft(9)+TrussSupport.F(r.Fy,"0.00").PadLeft(11)+TrussSupport.F(r.Fz,"0.00").PadLeft(11));if(rows.Count>60)b.AppendLine("... "+(rows.Count-60)+" more rows checked.");b.AppendLine();
  b.AppendLine("## 04  CHECKS (governing reaction row for each)");b.AppendLine("Check                          Clause          Node    L/C           Demand        Capacity      Ratio  Result");foreach(var c in checks)b.AppendLine(c.Name.PadRight(31)+c.Clause.PadRight(16)+c.Node.PadRight(8)+(c.Case.Length>12?c.Case.Substring(0,12):c.Case).PadRight(14)+(TrussSupport.F(c.Demand,"0.00")+" "+c.Unit).PadRight(14)+(TrussSupport.F(c.Capacity,"0.00")+" "+c.Unit).PadRight(14)+TrussSupport.F(c.Ratio,"0.00").PadRight(7)+(c.Ok?"OK":"NG")+"   "+c.Note);
  b.AppendLine();int ng=checks.Count(c=>!c.Ok);b.AppendLine(ng==0?"All checks satisfied for the reactions given.":ng+" check(s) not satisfied - revise the plate, anchors, gusset or welds.");b.AppendLine("Design calculation prepared with DTCE Tool Kit; it is not an engineer's approval. Confirm the support detail, anchor layout and reinforcement around the anchors on the structural drawings.");
  return b.ToString();}
}
